1	export interface PermissionUser {
2	  role?: string
3	  permissions?: string[]
4	}
5	
6	const WRITE_CAPABLE_ROLES = new Set(['admin', 'write'])
7	const READ_CAPABLE_ROLES = new Set(['admin', 'write', 'read'])
8	const ADMIN_ROLES = new Set(['admin'])
9	const CONFIG_READ_PERMISSION = 'config.read'
10	const CONFIG_DEPLOY_PERMISSION = 'config.deploy'
11	const CONFIG_WRITE_PERMISSION = 'config.write'
12	const EVALUATION_READ_PERMISSION = 'evaluation.read'
13	const EVALUATION_RUN_PERMISSION = 'evaluation.run'
14	const EVALUATION_WRITE_PERMISSION = 'evaluation.write'
15	const LOGS_READ_PERMISSION = 'logs.read'
16	const ML_PIPELINE_MANAGE_PERMISSION = 'mlpipeline.manage'
17	const MCP_READ_PERMISSION = 'mcp.read'
18	const MCP_MANAGE_PERMISSION = 'mcp.manage'
19	const OPENCLAW_READ_PERMISSION = 'openclaw.read'
20	const OPENCLAW_MANAGE_PERMISSION = 'openclaw.manage'
21	const REPLAY_READ_PERMISSION = 'replay.read'
22	const SECURITY_MANAGE_PERMISSION = 'security.manage'
23	const TOPOLOGY_READ_PERMISSION = 'topology.read'
24	const USERS_VIEW_PERMISSION = 'users.view'
25	const USERS_MANAGE_PERMISSION = 'users.manage'
26	
27	function hasPermission(user: PermissionUser | null | undefined, permission: string): boolean {
28	  return Array.isArray(user?.permissions) && user.permissions.includes(permission)
29	}
30	
31	function canAccessWithPermission(
32	  user: PermissionUser | null | undefined,
33	  permission: string,
34	  fallbackRoles: ReadonlySet<string> = WRITE_CAPABLE_ROLES,
35	): boolean {
36	  if (Array.isArray(user?.permissions)) {
37	    return hasPermission(user, permission)
38	  }
39	
40	  if (!user) return false
41	  const normalizedRole = typeof user.role === 'string' ? user.role.trim().toLowerCase() : ''
42	  return fallbackRoles.has(normalizedRole)
43	}
44	
45	export function canAccessReplayFlowDetails(user?: PermissionUser | null): boolean {
46	  // replay.read grants structural record access. The dashboard backend only leaves
47	  // request/response bodies and tool payloads unredacted for config writers.
48	  return canAccessWithPermission(user, CONFIG_WRITE_PERMISSION)
49	}
50	
51	export function canWriteConfig(user?: PermissionUser | null): boolean {
52	  return canAccessWithPermission(user, CONFIG_WRITE_PERMISSION)
53	}
54	
55	export function canDeployConfig(user?: PermissionUser | null): boolean {
56	  return canAccessWithPermission(user, CONFIG_DEPLOY_PERMISSION)
57	}
58	
59	export function canAccessMLSetup(user?: PermissionUser | null): boolean {
60	  return canAccessWithPermission(user, ML_PIPELINE_MANAGE_PERMISSION)
61	}
62	
63	export function canWriteEvaluation(user?: PermissionUser | null): boolean {
64	  return canAccessWithPermission(user, EVALUATION_WRITE_PERMISSION)
65	}
66	
67	export function canRunEvaluation(user?: PermissionUser | null): boolean {
68	  return canAccessWithPermission(user, EVALUATION_RUN_PERMISSION)
69	}
70	
71	export function canManageMCP(user?: PermissionUser | null): boolean {
72	  return canAccessWithPermission(user, MCP_MANAGE_PERMISSION)
73	}
74	
75	export function canManageOpenClaw(user?: PermissionUser | null): boolean {
76	  return canAccessWithPermission(user, OPENCLAW_MANAGE_PERMISSION)
77	}
78	
79	export function canManageSecurity(user?: PermissionUser | null): boolean {
80	  return canAccessWithPermission(user, SECURITY_MANAGE_PERMISSION, ADMIN_ROLES)
81	}
82	
83	export function canAccessDashboardPath(
84	  user: PermissionUser | null | undefined,
85	  pathname: string,
86	): boolean {
87	  const normalizedPath = pathname.trim().toLowerCase()
88	
89	  if (normalizedPath.startsWith('/users')) return canViewUsers(user)
90	  if (normalizedPath.startsWith('/ml-setup')) return canAccessMLSetup(user)
91	  if (normalizedPath.startsWith('/topology')) {
92	    return canAccessWithPermission(user, TOPOLOGY_READ_PERMISSION, READ_CAPABLE_ROLES)
93	  }
94	  if (
95	    normalizedPath.startsWith('/status') ||
96	    normalizedPath.startsWith('/logs') ||
97	    normalizedPath.startsWith('/monitoring') ||
98	    normalizedPath.startsWith('/tracing')
99	  ) {
100	    return canAccessWithPermission(user, LOGS_READ_PERMISSION, READ_CAPABLE_ROLES)
101	  }
102	  if (normalizedPath.startsWith('/insights')) {
