export interface PermissionUser {
  role?: string
  permissions?: string[]
}

const WRITE_CAPABLE_ROLES = new Set(['admin', 'write'])
const READ_CAPABLE_ROLES = new Set(['admin', 'write', 'read'])
const ADMIN_ROLES = new Set(['admin'])
const CONFIG_READ_PERMISSION = 'config.read'
const CONFIG_DEPLOY_PERMISSION = 'config.deploy'
const CONFIG_WRITE_PERMISSION = 'config.write'
const EVALUATION_READ_PERMISSION = 'evaluation.read'
const EVALUATION_RUN_PERMISSION = 'evaluation.run'
const EVALUATION_WRITE_PERMISSION = 'evaluation.write'
const LOGS_READ_PERMISSION = 'logs.read'
const ML_PIPELINE_MANAGE_PERMISSION = 'mlpipeline.manage'
const MCP_READ_PERMISSION = 'mcp.read'
const MCP_MANAGE_PERMISSION = 'mcp.manage'
const OPENCLAW_READ_PERMISSION = 'openclaw.read'
const OPENCLAW_MANAGE_PERMISSION = 'openclaw.manage'
const REPLAY_READ_PERMISSION = 'replay.read'
const SECURITY_MANAGE_PERMISSION = 'security.manage'
const TOPOLOGY_READ_PERMISSION = 'topology.read'
const USERS_VIEW_PERMISSION = 'users.view'
const USERS_MANAGE_PERMISSION = 'users.manage'

function hasPermission(user: PermissionUser | null | undefined, permission: string): boolean {
  return Array.isArray(user?.permissions) && user.permissions.includes(permission)
}

function canAccessWithPermission(
  user: PermissionUser | null | undefined,
  permission: string,
  fallbackRoles: ReadonlySet<string> = WRITE_CAPABLE_ROLES,
): boolean {
  if (Array.isArray(user?.permissions)) {
    return hasPermission(user, permission)
  }

  if (!user) return false
  const normalizedRole = typeof user.role === 'string' ? user.role.trim().toLowerCase() : ''
  return fallbackRoles.has(normalizedRole)
}

export function canAccessReplayFlowDetails(user?: PermissionUser | null): boolean {
  // replay.read grants structural record access. The dashboard backend only leaves
  // request/response bodies and tool payloads unredacted for config writers.
  return canAccessWithPermission(user, CONFIG_WRITE_PERMISSION)
}

export function canWriteConfig(user?: PermissionUser | null): boolean {
  return canAccessWithPermission(user, CONFIG_WRITE_PERMISSION)
}

export function canDeployConfig(user?: PermissionUser | null): boolean {
  return canAccessWithPermission(user, CONFIG_DEPLOY_PERMISSION)
}

export function canAccessMLSetup(user?: PermissionUser | null): boolean {
  return canAccessWithPermission(user, ML_PIPELINE_MANAGE_PERMISSION)
}

export function canWriteEvaluation(user?: PermissionUser | null): boolean {
  return canAccessWithPermission(user, EVALUATION_WRITE_PERMISSION)
}

export function canRunEvaluation(user?: PermissionUser | null): boolean {
  return canAccessWithPermission(user, EVALUATION_RUN_PERMISSION)
}

export function canManageMCP(user?: PermissionUser | null): boolean {
  return canAccessWithPermission(user, MCP_MANAGE_PERMISSION)
}

export function canManageOpenClaw(user?: PermissionUser | null): boolean {
  return canAccessWithPermission(user, OPENCLAW_MANAGE_PERMISSION)
}

export function canManageSecurity(user?: PermissionUser | null): boolean {
  return canAccessWithPermission(user, SECURITY_MANAGE_PERMISSION, ADMIN_ROLES)
}

export function canAccessDashboardPath(
  user: PermissionUser | null | undefined,
  pathname: string,
): boolean {
  const normalizedPath = pathname.trim().toLowerCase()

  if (normalizedPath.startsWith('/users')) return canViewUsers(user)
  if (normalizedPath.startsWith('/ml-setup')) return canAccessMLSetup(user)
  if (normalizedPath.startsWith('/topology')) {
    return canAccessWithPermission(user, TOPOLOGY_READ_PERMISSION, READ_CAPABLE_ROLES)
  }
  if (
    normalizedPath.startsWith('/status') ||
    normalizedPath.startsWith('/logs') ||
    normalizedPath.startsWith('/monitoring') ||
    normalizedPath.startsWith('/tracing')
  ) {
    return canAccessWithPermission(user, LOGS_READ_PERMISSION, READ_CAPABLE_ROLES)
  }
  if (normalizedPath.startsWith('/insights')) {
    return canAccessWithPermission(user, REPLAY_READ_PERMISSION, READ_CAPABLE_ROLES)
  }
  if (normalizedPath.startsWith('/evaluation')) {
    return canAccessWithPermission(user, EVALUATION_READ_PERMISSION, READ_CAPABLE_ROLES)
  }
  if (normalizedPath.startsWith('/clawos') || normalizedPath.startsWith('/openclaw')) {
    return canAccessWithPermission(user, OPENCLAW_READ_PERMISSION, READ_CAPABLE_ROLES)
  }
  if (normalizedPath.startsWith('/config/mcp')) {
    return canAccessWithPermission(user, MCP_READ_PERMISSION, READ_CAPABLE_ROLES)
  }
  if (
    normalizedPath.startsWith('/builder') ||
    normalizedPath.startsWith('/config') ||
    normalizedPath.startsWith('/knowledge-bases') ||
    normalizedPath.startsWith('/taxonomy') ||
    normalizedPath.startsWith('/security') ||
    normalizedPath.startsWith('/fleet-sim')
  ) {
    return canAccessWithPermission(user, CONFIG_READ_PERMISSION, READ_CAPABLE_ROLES)
  }

  return true
}

export function canViewUsers(user?: PermissionUser | null): boolean {
  if (Array.isArray(user?.permissions)) {
    return (
      hasPermission(user, USERS_VIEW_PERMISSION) || hasPermission(user, USERS_MANAGE_PERMISSION)
    )
  }

  return user?.role?.trim().toLowerCase() === 'admin'
}

export function canManageUsers(user?: PermissionUser | null): boolean {
  if (Array.isArray(user?.permissions)) {
    return hasPermission(user, USERS_MANAGE_PERMISSION)
  }

  return user?.role?.trim().toLowerCase() === 'admin'
}

export type RouteLoader = () => Promise<unknown>

export const loadLandingPage = () => import('../pages/LandingPage')
export const loadLoginPage = () => import('../pages/LoginPage')
export const loadBuilderPage = () => import('../pages/BuilderPage')
export const loadConfigPage = () => import('../pages/ConfigPage')
export const loadDashboardPage = () => import('../pages/DashboardPage')
export const loadEvaluationPage = () => import('../pages/EvaluationPage')
export const loadFleetSimFleetsPage = () => import('../pages/FleetSimFleetsPage')
export const loadFleetSimOverviewPage = () => import('../pages/FleetSimOverviewPage')
export const loadFleetSimRunsPage = () => import('../pages/FleetSimRunsPage')
export const loadFleetSimWorkloadsPage = () => import('../pages/FleetSimWorkloadsPage')
export const loadInsightsPage = () => import('../pages/InsightsPage')
export const loadInsightsRecordPage = () => import('../pages/InsightsRecordPage')
export const loadKnowledgeMapPage = () => import('../pages/KnowledgeMapPage')
export const loadLogsPage = () => import('../pages/LogsPage')
export const loadMLSetupPage = () => import('../pages/MLSetupPage')
export const loadMonitoringPage = () => import('../pages/MonitoringPage')
export const loadOpenClawPage = () => import('../pages/OpenClawPage')
export const loadPlaygroundFullscreenPage = () => import('../pages/PlaygroundFullscreenPage')
export const loadPlaygroundPage = () => import('../pages/PlaygroundPage')
export const loadSecurityPolicyPage = () => import('../pages/SecurityPolicyPage')
export const loadSetupWizardPage = () => import('../pages/SetupWizardPage')
export const loadStatusPage = () => import('../pages/StatusPage')
export const loadTaxonomyPage = () => import('../pages/TaxonomyPage')
export const loadTopologyPage = () => import('../pages/TopologyPage')
export const loadTracingPage = () => import('../pages/TracingPage')
export const loadUsersPage = () => import('../pages/UsersPage')

const routeLoaders: Array<{ matches: (pathname: string) => boolean; load: RouteLoader }> = [
  { matches: (pathname) => pathname === '/', load: loadLandingPage },
  { matches: (pathname) => pathname.startsWith('/login'), load: loadLoginPage },
  { matches: (pathname) => pathname.startsWith('/setup'), load: loadSetupWizardPage },
  { matches: (pathname) => pathname.startsWith('/dashboard'), load: loadDashboardPage },
  {
    matches: (pathname) => pathname.startsWith('/playground/fullscreen'),
    load: loadPlaygroundFullscreenPage,
  },
  { matches: (pathname) => pathname.startsWith('/playground'), load: loadPlaygroundPage },
  { matches: (pathname) => pathname.startsWith('/builder'), load: loadBuilderPage },
  { matches: (pathname) => pathname.startsWith('/config'), load: loadConfigPage },
  {
    matches: (pathname) => /^\/knowledge-bases\/[^/]+\/map\/?$/.test(pathname),
    load: loadKnowledgeMapPage,
  },
  { matches: (pathname) => pathname.startsWith('/knowledge-bases'), load: loadTaxonomyPage },
  { matches: (pathname) => pathname.startsWith('/topology'), load: loadTopologyPage },
  { matches: (pathname) => pathname.startsWith('/security'), load: loadSecurityPolicyPage },
  { matches: (pathname) => pathname.startsWith('/clawos'), load: loadOpenClawPage },
  { matches: (pathname) => /^\/insights\/[^/]+/.test(pathname), load: loadInsightsRecordPage },
  { matches: (pathname) => pathname.startsWith('/insights'), load: loadInsightsPage },
  { matches: (pathname) => pathname.startsWith('/evaluation'), load: loadEvaluationPage },
  {
    matches: (pathname) => pathname.startsWith('/fleet-sim/workloads'),
    load: loadFleetSimWorkloadsPage,
  },
  { matches: (pathname) => pathname.startsWith('/fleet-sim/fleets'), load: loadFleetSimFleetsPage },
  { matches: (pathname) => pathname.startsWith('/fleet-sim/runs'), load: loadFleetSimRunsPage },
  { matches: (pathname) => pathname.startsWith('/fleet-sim'), load: loadFleetSimOverviewPage },
  { matches: (pathname) => pathname.startsWith('/ml-setup'), load: loadMLSetupPage },
  { matches: (pathname) => pathname.startsWith('/status'), load: loadStatusPage },
  { matches: (pathname) => pathname.startsWith('/logs'), load: loadLogsPage },
  { matches: (pathname) => pathname.startsWith('/monitoring'), load: loadMonitoringPage },
  { matches: (pathname) => pathname.startsWith('/tracing'), load: loadTracingPage },
  { matches: (pathname) => pathname.startsWith('/users'), load: loadUsersPage },
]

const routePreloads = new Map<RouteLoader, Promise<unknown>>()

export function resetDashboardRouteLoader(loader: RouteLoader): void {
  routePreloads.delete(loader)
}

export function preloadDashboardRoute(pathname: string): Promise<unknown> | undefined {
  const loader = routeLoaders.find((route) => route.matches(pathname))?.load
  if (!loader) return undefined

  const existing = routePreloads.get(loader)
  if (existing) return existing

  const preload = loader().catch(() => {
    routePreloads.delete(loader)
    // Intent preloading is opportunistic; do not turn a hover/focus fetch
    // failure into an unhandled rejection before the user actually navigates.
    return undefined
  })
  routePreloads.set(loader, preload)
  return preload
}

import React from 'react'
import { Navigate, Outlet, useLocation } from 'react-router-dom'
import OnboardingGuide from '../components/OnboardingGuide'
import { useSetup } from '../contexts/SetupContext'

/** Setup-mode redirect + onboarding for normal routes. */
const AuthenticatedShell: React.FC = () => {
  const { setupState } = useSetup()
  const location = useLocation()
  const isSetupMode = setupState?.setupMode ?? false

  if (isSetupMode && location.pathname !== '/setup') {
    return <Navigate to="/setup" replace />
  }

  if (!isSetupMode && location.pathname === '/setup') {
    return <Navigate to="/dashboard" replace />
  }

  return (
    <>
      <Outlet />
      {!isSetupMode && location.pathname !== '/setup' && <OnboardingGuide />}
    </>
  )
}

export default AuthenticatedShell

import React, { useEffect, useState, useCallback, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import RouterModelInventory from '../components/RouterModelInventory'
import { useAuth } from '../contexts/AuthContext'
import { canAccessMLSetup } from '../utils/accessControl'
import {
  getLoadedModelCount,
  getModelStatusSummary,
  getRouterModelAnchor,
  getTotalKnownModelCount,
  type SystemStatus,
} from '../utils/routerRuntime'
import { DashboardMiniFlowDiagram } from './DashboardMiniFlowDiagram'
import type { RouterConfig } from './dashboardPageTypes'
import {
  categorizeDecisions,
  countDecisions,
  countModels,
  countPlugins,
  countSignals,
} from './dashboardPageStats'
import { buildDecisionPreviewRows, buildSignalBreakdownRows } from './dashboardPageOverview'
import { createVisibilityAwareRequest } from './visibilityAwareRequest'
import styles from './DashboardPage.module.css'

const DashboardPage: React.FC = () => {
  const navigate = useNavigate()
  const { user } = useAuth()

  const [config, setConfig] = useState<RouterConfig | null>(null)
  const [status, setStatus] = useState<SystemStatus | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)

  const fetchStatus = useCallback(async () => {
    const statusRes = await fetch('/api/status')
    if (statusRes.ok) {
      setStatus(await statusRes.json())
    }
  }, [])

  const fetchConfig = useCallback(async () => {
    const configResult = await fetch('/api/router/config/all')
    if (configResult.ok) {
      setConfig(await configResult.json())
      setLastUpdated(new Date())
      setError(null)
    }
  }, [])

  const statusRequest = useMemo(() => createVisibilityAwareRequest(fetchStatus), [fetchStatus])
  const configRequest = useMemo(() => createVisibilityAwareRequest(fetchConfig), [fetchConfig])

  const fetchAll = useCallback(async (manual = false) => {
    if (manual) setRefreshing(true)
    try {
      await Promise.all([
        configRequest.run({ allowHidden: true }),
        statusRequest.run({ allowHidden: true }),
      ])
      setLastUpdated(new Date())
      setError(null)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load dashboard data')
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [configRequest, statusRequest])

  useEffect(() => {
    const pollStatus = () => {
      void statusRequest.run().catch(() => {
        // Ignore transient status polling errors.
      })
    }
    const pollConfig = () => {
      void configRequest.run().catch((pollError) => {
        setError(pollError instanceof Error ? pollError.message : 'Failed to refresh dashboard config')
      })
    }
    const onVisibilityChange = () => {
      if (!document.hidden) {
        pollStatus()
        pollConfig()
      }
    }
    const onConfigDeployed = () => {
      void fetchAll()
    }

    void fetchAll()
    const statusInterval = window.setInterval(pollStatus, 10000)
    const configInterval = window.setInterval(pollConfig, 30000)
    window.addEventListener('config-deployed', onConfigDeployed)
    document.addEventListener('visibilitychange', onVisibilityChange)
    return () => {
      window.clearInterval(statusInterval)
      window.clearInterval(configInterval)
      window.removeEventListener('config-deployed', onConfigDeployed)
      document.removeEventListener('visibilitychange', onVisibilityChange)
    }
  }, [configRequest, fetchAll, statusRequest])

  const signalStats = useMemo(() => (config ? countSignals(config) : { total: 0, byType: {} }), [config])
  const decisionCount = useMemo(() => (config ? countDecisions(config) : 0), [config])
  const modelCount = useMemo(() => (config ? countModels(config) : 0), [config])
  const pluginCount = useMemo(() => (config ? countPlugins(config) : 0), [config])
  const currentDecisions = useMemo(() => config?.routing?.decisions ?? config?.decisions ?? [], [config])
  const healthyServices = useMemo(() => status?.services.filter(s => s.healthy).length ?? 0, [status])
  const showMLSetupQuickLink = canAccessMLSetup(user)
  const totalServices = useMemo(() => status?.services.length ?? 0, [status])
  const modelStatus = useMemo(() => getModelStatusSummary(status), [status])
  const loadedModels = useMemo(() => getLoadedModelCount(status?.models), [status])
  const knownModels = useMemo(() => getTotalKnownModelCount(status?.models), [status])
  const previewModelLimit = 6

  const categorizedDecisions = useMemo(
    () => (config ? categorizeDecisions(config) : { guardrails: [], routing: [], fallbacks: [] }),
    [config],
  )
  const signalBreakdownRows = useMemo(
    () => buildSignalBreakdownRows(signalStats.byType),
    [signalStats.byType],
  )
  const decisionPreviewRows = useMemo(
    () => buildDecisionPreviewRows([
      ...categorizedDecisions.guardrails,
      ...categorizedDecisions.routing,
      ...categorizedDecisions.fallbacks,
    ]),
    [categorizedDecisions],
  )

  if (loading && !config && !status) {
    return (
      <div className={styles.page}>
        <div className={styles.loading}>
          <div className={styles.spinner} />
          <p>Loading dashboard...</p>
        </div>
      </div>
    )
  }

  return (
    <div className={styles.page}>
      <div className={styles.header}>
        <div>
          <h1 className={styles.title}>Building Mixture-of-Models</h1>
          <p className={styles.subtitle}>
            The next-generation model architecture for heterogeneous LLM inference.
          </p>
        </div>
        <div className={styles.headerActions}>
          {lastUpdated && (
            <span className={styles.lastUpdated}>
              Updated {lastUpdated.toLocaleTimeString()}
            </span>
          )}
          <button
            className={`${styles.refreshBtn} ${refreshing ? styles.refreshBtnSpin : ''}`}
            onClick={() => fetchAll(true)}
            disabled={refreshing}
          >
            <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
              <path d="M14 8A6 6 0 1 1 8 2" strokeLinecap="round" />
              <path d="M14 2v6h-6" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            {refreshing ? 'Refreshing...' : 'Refresh'}
          </button>
        </div>
      </div>

      {error && (
        <div className={styles.errorBanner}>
          <span>Failed to load data: {error}</span>
          <button onClick={() => fetchAll(true)}>Retry</button>
        </div>
      )}

      <div className={styles.statsGrid}>
        <button type="button" className={styles.statCard} onClick={() => navigate('/config/models')}>
          <div className={styles.statIcon}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <rect x="2" y="3" width="20" height="18" rx="3" />
              <path d="M8 7v10M12 7v10M16 7v10" />
            </svg>
          </div>
          <div className={styles.statContent}>
            <span className={styles.statValue}>{modelCount}</span>
            <span className={styles.statLabel}>Models</span>
          </div>
          <span className={styles.statArrow}>&rsaquo;</span>
        </button>

        <button type="button" className={styles.statCard} onClick={() => navigate('/config/decisions')}>
          <div className={styles.statIcon}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M4 6h16M4 12h8M4 18h12" />
            </svg>
          </div>
          <div className={styles.statContent}>
            <span className={styles.statValue}>{decisionCount}</span>
            <span className={styles.statLabel}>Decisions</span>
          </div>
          <span className={styles.statArrow}>&rsaquo;</span>
        </button>

        <button type="button" className={styles.statCard} onClick={() => navigate('/config/signals')}>
          <div className={styles.statIcon}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <circle cx="12" cy="12" r="3" />
              <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
            </svg>
          </div>
          <div className={styles.statContent}>
            <span className={styles.statValue}>{signalStats.total}</span>
            <span className={styles.statLabel}>Signals</span>
          </div>
          <span className={styles.statArrow}>&rsaquo;</span>
        </button>

        <button type="button" className={styles.statCard} onClick={() => navigate('/status')}>
          <div className={`${styles.statIcon} ${
            status?.overall === 'healthy' ? styles.statIconHealthy :
            status?.overall === 'degraded' ? styles.statIconDegraded :
            styles.statIconDown
          }`}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round">
              <path d="M22 12h-4l-3 9L9 3l-3 9H2" />
            </svg>
          </div>
          <div className={styles.statContent}>
            <span className={styles.statValue}>{healthyServices}/{totalServices}</span>
            <span className={styles.statLabel}>Services Healthy</span>
          </div>
          <span className={styles.statArrow}>&rsaquo;</span>
        </button>

        <button type="button" className={styles.statCard} onClick={() => navigate('/status')}>
          <div className={`${styles.statIcon} ${
            modelStatus.tone === 'ok' ? styles.statIconHealthy :
            modelStatus.tone === 'warn' ? styles.statIconStarting :
            styles.statIconDown
          }`}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12 3v10" />
              <path d="M8.5 9.5 12 13l3.5-3.5" />
              <path d="M4 19h16" />
            </svg>
          </div>
          <div className={styles.statContent}>
            <span className={styles.statValue}>{modelStatus.value}</span>
            <span className={styles.statLabel}>Model Status</span>
            <span className={styles.statDetail}>{modelStatus.detail}</span>
          </div>
          <span className={styles.statArrow}>&rsaquo;</span>
        </button>
      </div>

      <div className={styles.mainGrid}>
        <div className={styles.card}>
          <div className={styles.cardHeader}>
            <h2 className={styles.cardTitle}>Intelligence Layers</h2>
            <button type="button" className={styles.cardAction} onClick={() => navigate('/topology')}>
              View Full Layers &rsaquo;
            </button>
          </div>
          <div className={styles.flowContainer}>
            {config ? (
              <DashboardMiniFlowDiagram
                signals={signalStats}
                decisions={decisionCount}
                models={modelCount}
                plugins={pluginCount}
              />
            ) : (
              <div className={styles.emptyState}>No configuration loaded</div>
            )}
          </div>
        </div>

        <div className={styles.rightCol}>
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <h2 className={styles.cardTitle}>System Health</h2>
              <button type="button" className={styles.cardAction} onClick={() => navigate('/status')}>
                Details &rsaquo;
              </button>
            </div>
            <div className={styles.healthContent}>
              {status ? (
                <>
                  <div className={styles.healthOverall}>
                    <span className={`${styles.healthDot} ${
                      status.overall === 'healthy' ? styles.healthDotGreen :
                      status.overall === 'degraded' ? styles.healthDotYellow :
                      styles.healthDotRed
                    }`}
                    />
                    <span className={styles.healthLabel}>
                      {status.overall === 'not_running' ? 'Not Running' :
                       status.overall.charAt(0).toUpperCase() + status.overall.slice(1)}
                    </span>
                    {status.version && <span className={styles.versionBadge}>{status.version}</span>}
                    {status.deployment_type && status.deployment_type !== 'none' && (
                      <span className={styles.deployBadge}>{status.deployment_type}</span>
                    )}
                  </div>
                  <div className={styles.servicesList}>
                    {status.services.slice(0, 6).map((svc, i) => (
                      <div key={i} className={styles.serviceRow}>
                        <span className={`${styles.svcDot} ${svc.healthy ? styles.svcDotOk : styles.svcDotFail}`} />
                        <span className={styles.svcName}>{svc.name}</span>
                        <span className={`${styles.svcStatus} ${svc.healthy ? styles.svcStatusOk : styles.svcStatusFail}`}>
                          {svc.status}
                        </span>
                      </div>
                    ))}
                    {status.services.length > 6 && (
                      <div className={styles.moreServices}>+{status.services.length - 6} more</div>
                    )}
                  </div>
                </>
