import type { DecisionRule, RouterConfig } from './dashboardPageTypes'

export function countSignals(cfg: RouterConfig): { total: number; byType: Record<string, number> } {
  const byType: Record<string, number> = {}
  let total = 0
  const signals = cfg.routing?.signals ?? cfg.signals
  if (signals) {
    for (const [type, arr] of Object.entries(signals)) {
      if (Array.isArray(arr)) {
        byType[type] = arr.length
        total += arr.length
      }
    }
  }
  return { total, byType }
}

export function countDecisions(cfg: RouterConfig): number {
  const decisions = cfg.routing?.decisions ?? cfg.decisions
  return Array.isArray(decisions) ? decisions.length : 0
}

export function countModels(cfg: RouterConfig): number {
  const models = cfg.providers?.models
  if (Array.isArray(models)) {
    return models.length
  }

  const legacyRootEndpoints = cfg.vllm_endpoints
  if (Array.isArray(legacyRootEndpoints)) return legacyRootEndpoints.length

  const legacyProviderEndpoints = cfg.providers?.vllm_endpoints
  return Array.isArray(legacyProviderEndpoints) ? legacyProviderEndpoints.length : 0
}

export function countPlugins(cfg: RouterConfig): number {
  const decisions = cfg.routing?.decisions ?? cfg.decisions
  if (Array.isArray(decisions)) {
    return decisions.reduce((count, decision) => count + (Array.isArray(decision.plugins) ? decision.plugins.length : 0), 0)
  }
  if (!cfg.plugins || typeof cfg.plugins !== 'object') return 0
  return Object.keys(cfg.plugins).length
}

/** Classify decision by priority range */
export function getDecisionCategory(priority?: number): 'guardrail' | 'routing' | 'fallback' {
  if (priority == null) return 'routing'
  if (priority >= 999) return 'guardrail'
  if (priority <= 100) return 'fallback'
  return 'routing'
}

/** Palette for signal type labels (flow diagram + breakdown). */
export const SIGNAL_COLORS: Record<string, string> = {
  keywords: '#4EC9B0',
  embeddings: '#9CDCFE',
  domains: '#DCDCAA',
  fact_check: '#CE9178',
  user_feedbacks: '#C586C0',
  reasks: '#FFB454',
  preferences: '#4FC1FF',
  language: '#B5CEA8',
  context: '#D7BA7D',
  complexity: '#569CD6',
  modality: '#D4D4D4',
  authz: '#F48771',
  jailbreak: '#F48771',
  pii: '#FF6B6B',
}

export function categorizeDecisions(config: RouterConfig | null): {
  guardrails: DecisionRule[]
  routing: DecisionRule[]
  fallbacks: DecisionRule[]
} {
  const decisions = config?.routing?.decisions ?? config?.decisions
  if (!decisions) return { guardrails: [], routing: [], fallbacks: [] }
  const guardrails: DecisionRule[] = []
  const routing: DecisionRule[] = []
  const fallbacks: DecisionRule[] = []
  for (const d of decisions) {
    const cat = getDecisionCategory(d.priority)
    if (cat === 'guardrail') guardrails.push(d)
    else if (cat === 'fallback') fallbacks.push(d)
    else routing.push(d)
  }
  return { guardrails, routing, fallbacks }
}

import {
  Component,
  Suspense,
  lazy,
  useMemo,
  useState,
  type ComponentType,
  type ErrorInfo,
  type ReactNode,
} from 'react'

import RouteLoadingFallback from './RouteLoadingFallback'
import { resetDashboardRouteLoader, type RouteLoader } from './routeLoaders'
import { getRouteLoadFailureCopy, routeLoadErrorMessage } from './routeLoadFailureSupport'
import styles from './RecoverableLazyRoute.module.css'

interface RouteLoadErrorBoundaryProps {
  children: ReactNode
  routeLabel: string
  onRetry: () => void
}

interface RouteLoadErrorBoundaryState {
  error: Error | null
}

class RouteLoadErrorBoundary extends Component<
  RouteLoadErrorBoundaryProps,
  RouteLoadErrorBoundaryState
> {
  private retryButton: HTMLButtonElement | null = null

  state: RouteLoadErrorBoundaryState = { error: null }

  static getDerivedStateFromError(error: Error): RouteLoadErrorBoundaryState {
    return { error }
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Lazy dashboard route failed:', error, errorInfo)
  }

  componentDidUpdate(
    _previousProps: RouteLoadErrorBoundaryProps,
    previousState: RouteLoadErrorBoundaryState,
  ) {
    if (!previousState.error && this.state.error) {
      window.requestAnimationFrame(() => this.retryButton?.focus())
    }
  }

  render() {
    const { error } = this.state
    if (!error) return this.props.children

    const copy = getRouteLoadFailureCopy(error, this.props.routeLabel)
    return (
      <section className={styles.surface} role="alert" data-testid="route-load-error">
        <div className={styles.panel}>
          <span className={styles.eyebrow}>{copy.eyebrow}</span>
          <h1 className={styles.title}>{copy.title}</h1>
          <p className={styles.description}>{copy.description}</p>
          <div className={styles.actions}>
            <button
              ref={(element) => {
                this.retryButton = element
              }}
              type="button"
              className={styles.primaryButton}
              onClick={this.props.onRetry}
            >
              Retry route
            </button>
            <button
              type="button"
              className={styles.secondaryButton}
              onClick={() => window.location.reload()}
            >
              Reload dashboard
            </button>
          </div>
          <details className={styles.details}>
            <summary>Technical details</summary>
            <code>{routeLoadErrorMessage(error)}</code>
          </details>
        </div>
      </section>
    )
  }
}

export interface RecoverableLazyRouteProps<Props extends object> {
  loader: () => Promise<{ default: ComponentType<Props> }>
  routeLabel: string
  componentProps?: Props
}

function createRetryableLazyPage<Props extends object>(
  loader: RecoverableLazyRouteProps<Props>['loader'],
  _attempt: number,
) {
  return lazy(loader)
}

export default function RecoverableLazyRoute<Props extends object = Record<string, never>>({
  loader,
  routeLabel,
  componentProps,
}: RecoverableLazyRouteProps<Props>) {
  const [attempt, setAttempt] = useState(0)
  const LazyPage = useMemo(() => createRetryableLazyPage(loader, attempt), [attempt, loader])
  const RenderablePage = LazyPage as unknown as ComponentType<Record<string, unknown>>
  const renderProps = (componentProps ?? {}) as Record<string, unknown>

  const handleRetry = () => {
    resetDashboardRouteLoader(loader as RouteLoader)
    setAttempt((current) => current + 1)
  }

  return (
    <RouteLoadErrorBoundary key={attempt} routeLabel={routeLabel} onRetry={handleRetry}>
      <Suspense fallback={<RouteLoadingFallback />}>
        <RenderablePage {...renderProps} />
      </Suspense>
    </RouteLoadErrorBoundary>
  )
}

import type { DecisionRule } from './dashboardPageTypes'
import { getDecisionCategory, SIGNAL_COLORS } from './dashboardPageStats'

export interface SignalBreakdownRow {
  type: string
  count: number
  percent: number
  color: string
}

export interface DecisionPreviewRow {
  key: string
  name: string
  title: string
  priorityLabel: number | string
  category: ReturnType<typeof getDecisionCategory>
  typeLabel: string
  modelNames: string
}

export function buildSignalBreakdownRows(byType: Record<string, number>): SignalBreakdownRow[] {
  const entries = Object.entries(byType).filter(([, count]) => count > 0)
  if (entries.length === 0) return []

  const maxCount = Math.max(...entries.map(([, count]) => count))
  return entries
    .sort((a, b) => b[1] - a[1])
    .map(([type, count]) => ({
      type,
      count,
      percent: Math.round((count / maxCount) * 100),
      color: SIGNAL_COLORS[type] || '#999',
    }))
}

export function buildDecisionPreviewRows(
  decisions: readonly DecisionRule[],
  limit = 10,
): DecisionPreviewRow[] {
  return decisions.slice(0, limit).map((decision, index) => {
    const category = getDecisionCategory(decision.priority)
    const name = decision.name || `Decision ${index + 1}`
    return {
      key: `${name}-${index}`,
      name,
      title: decision.description || decision.name || '',
      priorityLabel: decision.priority ?? '—',
      category,
      typeLabel: category === 'guardrail' ? 'Guard' : category === 'fallback' ? 'Default' : 'Route',
      modelNames: formatDecisionModelNames(decision.modelRefs),
    }
  })
}

function formatDecisionModelNames(modelRefs: unknown): string {
  if (!Array.isArray(modelRefs)) return '—'
  return modelRefs.map(modelRefName).filter(Boolean).join(', ')
}

function modelRefName(modelRef: unknown): string {
  if (!modelRef || typeof modelRef !== 'object') return ''
  const model = (modelRef as { model?: unknown }).model
  return typeof model === 'string' ? model : ''
}

